<?php require __DIR__.'/includes/core.php';if(me())go(dashboard_path(me()['role']));$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$u=one('SELECT * FROM users WHERE phone=? AND is_active=1',[phone($_POST['phone']??'')]);if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'role'=>$u['role']];go($u['must_change_password']?'password.php':dashboard_path($u['role']));}usleep(350000);$error='Invalid credentials or inactive account.';}ob_start();?><div class="card" style="max-width:480px;margin:auto"><p>Confidential staff evaluation portal</p><?php if($error)echo '<div class="alert error">'.h($error).'</div>';?><form method="post"><?=token()?><label>Registered phone number</label><input name="phone" required autocomplete="username"><label>Password</label><input type="password" name="password" required autocomplete="current-password"><p><button>Sign in</button></p></form><p class="muted small">First installation? Open <code>setup.php</code> after importing the SQL file.</p></div><?php layout('Sign in',ob_get_clean());